if (!bins) return false;

    T min_cost = std::numeric_limits<T>::max();
    int best_axis = -1;
    T best_pos = 0;

    for (int axis = 0; axis < 3; ++axis) {
        T axis_min = bmin[axis];
        T axis_max = bmax[axis];
        T axis_range = axis_max - axis_min;

        if (axis_range <= 0) continue;

        // The BinBuffer typically contains counts of primitives in each bin.
        // We iterate through the bins to find the split that minimizes SAH.
        // SAH Cost = C_trav + (SA(L)/SA(Parent) * N(L) * C_isect) + (SA(R)/SA(Parent) * N(R) * C_isect)
        // Since C_trav, C_isect, and SA(Parent) are constant for a specific node,
        // we minimize: SA(L) * N(L) + SA(R) * N(R)

        int num_bins = bins->num_bins;
        std::vector<int> count_left(num_bins, 0);
        std::vector<int> count_right(num_bins, 0);

        int total_prims = 0;
        for (int i = 0; i < num_bins; ++i) {
            total_prims += bins->counts[i];
        }

        int current_left_count = 0;
        for (int i = 0; i < num_bins; ++i) {
            current_left_count += bins->counts[i];
            count_left[i] = current_left_count;
        }

        int current_right_count = 0;
        for (int i = num_bins - 1; i >= 0; --i) {
            current_right_count += bins->counts[i];
            count_right[i] = current_right_count;
        }

        for (int i = 0; i < num_bins - 1; ++i) {
            T split_pos = axis_min + (T)(i + 1) * (axis_range / num_bins);

            // Approximate surface area of children
            // For a split along one axis, the other two dimensions of the bounding box remain the same.
            // SA = 2 * (w*h + h*d + d*w)
            // Let Area_other = 2 * (bmax[y]-bmin[y])*(bmax[z]-bmin[z]) etc.
            T sa_left = 0;
            T sa_right = 0;

            T d0 = bmax[0] - bmin[0];
            T d1 = bmax[1] - bmin[1];
            T d2 = bmax[2] - bmin[2];

            T common_area = 0;
            T left_dim = split_pos - axis_min;
            T right_dim = axis_max - split_pos;

            if (axis == 0) {
                common_area = d1 * d2;
                sa_left = common_area * (d1 + d2 + left_dim);
                sa_right = common_area * (d1 + d2 + right_dim);
            } else if (axis == 1) {
                common_area = d0 * d2;
                sa_left = common_area * (d0 + d2 + left_dim);
                sa_right = common_area * (d0 + d2 + right_dim);
            } else {
                common_area = d0 * d1;
                sa_left = common_area * (d0 + d1 + left_dim);
                sa_right = common_area * (d0 + d1 + right_dim);
            }

            T cost = sa_left * count_left[i] + sa_right * count_right[i + 1];
            if (cost < min_cost) {
                min_cost = cost;
                best_axis = axis;
                best_pos = split_pos;
            }
        }
    }

    if (best_axis == -1) return false;

    *minCostAxis = best_axis;
    for (int i = 0; i < 3; ++i) {
        cut_pos[i] = (i == best_axis) ? best_pos : (bmin[i] + bmax[i]) * 0.5f;
    }

    return true;

